package net.officefloor.hq.app.person;

/** One of a person's patrons: another person on the same sheet, by id. */
public record Patron(long personId, long patronId) {
}
package net.officefloor.hq.app.person;

import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class PatronRepository {

    private final JdbcTemplate jdbc;

    public PatronRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every patron named on the sheet, by person. */
    public List<Patron> list(String sheetId) {
        return jdbc.query("SELECT person_id, patron_id FROM patron WHERE sheet_id = ? ORDER BY person_id, patron_id",
                (rs, i) -> new Patron(rs.getLong("person_id"), rs.getLong("patron_id")), sheetId);
    }

    /** Whether the person has already named this patron. */
    public boolean named(String sheetId, long personId, long patronId) {
        Integer known = jdbc.queryForObject(
                "SELECT COUNT(*) FROM patron WHERE sheet_id = ? AND person_id = ? AND patron_id = ?", Integer.class,
                sheetId, personId, patronId);
        return known != null && known > 0;
    }

    public void add(String sheetId, long personId, long patronId) {
        jdbc.update("INSERT INTO patron (sheet_id, person_id, patron_id) VALUES (?, ?, ?)", sheetId, personId,
                patronId);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Name another person on the sheet as one of a person's patrons: not themselves, and not one they
 *  have already named. */
public class AddPatron {
    public void add(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            @RequestBody PatronRequest request, ServerHttpConnection connection, PersonRepository repository,
            PatronRepository patrons, Audit audit, Out<Person> person) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long pid;
        try {
            pid = Long.parseLong(personId == null ? "" : personId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such person");
        }
        Person found = repository.find(id, pid);
        if (found == null) {
            throw new BadRequestException("no such person");
        }
        Person patron = request == null || request.patronId() == null ? null : repository.find(id, request.patronId());
        if (patron == null) {
            throw new BadRequestException("choose a person on the sheet as patron");
        }
        if (patron.id() == pid) {
            throw new BadRequestException("a person cannot be their own patron");
        }
        if (patrons.named(id, pid, patron.id())) {
            throw new BadRequestException(patron.name() + " is already a patron of " + found.name());
        }
        try {
            patrons.add(id, pid, patron.id());
        } catch (DuplicateKeyException e) {
            throw new BadRequestException(patron.name() + " is already a patron of " + found.name());
        }
        audit.record("PATRON_ADDED sheet=" + id + " by=" + by + " name=" + found.name() + " patron=" + patron.name());
        person.set(found);
    }
}
package net.officefloor.hq.app.person;

import java.util.List;

/** A sheet's people, in the order they were added, and every patron any of them has named, and the ids of
 *  the people the signed-in user watches, and every alias any of them has. */
public record People(List<Person> people, List<Patron> patrons, List<Long> watched, List<Alias> aliases) {
}
-- A person's patrons: other people on the same sheet they have named, each at most once.
CREATE TABLE patron (
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    patron_id BIGINT       NOT NULL REFERENCES person (id),
    PRIMARY KEY (person_id, patron_id)
);
CREATE INDEX patron_sheet ON patron (sheet_id);
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { patronsKey, usePatrons, usePeople, type Person } from '../people/usePeople';
import { useClaims } from '../claims/useClaims';
import { sumDues } from '../rates/useRates';
import { useSheetToday } from '../today/useSheetToday';

/** The first day (yyyy-mm-dd) of the 90 days up to and including a day. */
function windowStart(today: string): string {
  return new Date(Date.parse(`${today}T00:00:00Z`) - 89 * 86_400_000).toISOString().slice(0, 10);
}

/** A person's patrons: the other people on the sheet they have named (names sorted, comma and space
 *  separated), their backing (the due frozen when each of their patrons' SETTLED claims dated within the 90 days up
 *  to and including the sheet's today was settled, added up; 0.00 with none),
 *  and a picker that names one more. Naming themselves, or a patron twice, is refused. */
function PersonPatrons({ sheetId, personId }: { sheetId: string; personId: number }) {
  const people = usePeople(sheetId);
  const patrons = usePatrons(sheetId);
  const claims = useClaims(sheetId);
  const today = useSheetToday(sheetId).data?.today;
  const queryClient = useQueryClient();
  const [chosen, setChosen] = useState('');

  const named = (patrons.data ?? [])
    .filter((x) => x.personId === personId)
    .map((x) => people.data?.find((p) => p.id === x.patronId))
    .filter((p): p is Person => p !== undefined);
  const names = named.map((p) => p.name).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const from = today === undefined ? undefined : windowStart(today);
  const patronIds = new Set(named.map((p) => p.id));
  const backing = sumDues((claims.data ?? [])
    .filter((c) => patronIds.has(c.personId) && c.status === 'SETTLED' && c.due !== null
      && from !== undefined && today !== undefined && c.date >= from && c.date <= today)
    .map((c) => c.due as string));

  const add = useMutation({
    mutationFn: (patronId: number) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/patrons`, { patronId }),
    onSuccess: async () => {
      setChosen('');
      await queryClient.invalidateQueries({ queryKey: patronsKey(sheetId) });
    },
  });

  return (
    <>
      <td data-testid="person-patrons">{names.join(', ')}</td>
      <td data-testid="person-backing">{backing}</td>
      <td>
        <select
          data-testid="person-patron-select"
          value={chosen}
          onChange={(e) => {
            setChosen(e.target.value);
            add.reset();
          }}
        >
          <option value="">Patron…</option>
          {(people.data ?? []).map((p) => (
            <option key={p.id} value={String(p.id)}>
              {p.name}
            </option>
          ))}
        </select>{' '}
        <button
          type="button"
          data-testid="person-patron-add"
          disabled={add.isPending}
          onClick={() => {
            add.reset();
            add.mutate(Number(chosen));
          }}
        >
          Add patron
        </button>
        {add.isError && <span data-testid="person-patron-error">{add.error.message}</span>}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumnHead.fill({
    order: 50,
    Component: () => (
      <>
        <th>Patrons</th>
        <th>Backing</th>
        <th />
      </>
    ),
  }),
  PersonCells.fill({ order: 50, Component: PersonPatrons }),
];
